/**
 * src/assets/saloon/SaloonMaterials.ts
 * -----------------------------------------------------------------------------
 * Shared saloon PALETTE + per-object material sets.
 *
 * Disposal contract: ThreeRendererAdapter.disposeObject3D() disposes every
 * material it finds in a managed object's subtree. Materials must therefore
 * be created PER FACTORY CALL (createSaloonMaterials()) and shared only
 * WITHIN one produced object — never as cross-object module singletons,
 * or deleting one prop would dispose a material still used by another.
 *
 * Performance rules honoured here:
 *   - No textures; MeshStandardMaterial only (DayNightCycle-lit).
 *   - OPAQUE "glass" (dark, semi-smooth) — transparency only where it is
 *     genuinely needed, and the saloon needs it nowhere.
 *   - Low roughness variance; no env maps.
 * -----------------------------------------------------------------------------
 */

import * as THREE from 'three';

/** Shared saloon palette (linear-space hex colors). */
export const SALOON_PALETTE = Object.freeze({
  woodDark: 0x5a3722,
  woodMed: 0x8a5a34,
  woodLight: 0xa9764c,
  brass: 0xb08d3d,
  iron: 0x2b2b2b,
  glassDark: 0x1c2a33,
  feltGreen: 0x225533,
  mirror: 0xbfd8e0,
  paper: 0xe8dcc0,
  ink: 0x2a2016,
  flame: 0xffb066,
  ivory: 0xf0ead6,
  leather: 0x5d3a24,
  leatherDark: 0x3a2318,
  silk: 0x7a1f2b,
  amber: 0xa8642a,
  /** Burgundy table wine (opaque liquid inside wine glasses). */
  wine: 0x5a1420,
  /** Bottle-glass colours — OPAQUE so bottles never vanish. */
  bottleGreen: 0x24402c,
  bottleBrown: 0x3a2416,
  bottleAmber: 0x7a4a20,
  bottleOlive: 0x4a4a2a,
  /** Cork stoppers. */
  cork: 0x9a7040,
  /** Darker brass (spittoon interiors, shaded trim). */
  brassDark: 0x6b5526,
});

export interface SaloonMaterials {
  woodDark: THREE.MeshStandardMaterial;
  woodMed: THREE.MeshStandardMaterial;
  woodLight: THREE.MeshStandardMaterial;
  brass: THREE.MeshStandardMaterial;
  iron: THREE.MeshStandardMaterial;
  glassDark: THREE.MeshStandardMaterial;
  felt: THREE.MeshStandardMaterial;
  mirror: THREE.MeshStandardMaterial;
  paper: THREE.MeshStandardMaterial;
  ink: THREE.MeshStandardMaterial;
  /** Emissive flame chip — glows without adding a real light. */
  flame: THREE.MeshStandardMaterial;
  /** Dark lamp glass for lantern bodies. */
  lampGlass: THREE.MeshStandardMaterial;
  /** Ivory key/cards/chips surface. */
  ivory: THREE.MeshStandardMaterial;
  /** Upholstery leather (armrest, stool tops). */
  leather: THREE.MeshStandardMaterial;
  /** Dark leather (card deck box). */
  leatherDark: THREE.MeshStandardMaterial;
  /** Red silk decorative panel. */
  silk: THREE.MeshStandardMaterial;
  /** Amber whiskey inside the glass. */
  amber: THREE.MeshStandardMaterial;
  /** Burgundy wine liquid (opaque). */
  wine: THREE.MeshStandardMaterial;
  /** Opaque bottle glass — dark green (tall bottles). */
  bottleGreen: THREE.MeshStandardMaterial;
  /** Opaque bottle glass — dark brown (whiskey bottles). */
  bottleBrown: THREE.MeshStandardMaterial;
  /** Opaque bottle glass — amber (bourbon bottles). */
  bottleAmber: THREE.MeshStandardMaterial;
  /** Opaque bottle glass — brown/olive (old squat bottles). */
  bottleOlive: THREE.MeshStandardMaterial;
  /** Cork stoppers. */
  cork: THREE.MeshStandardMaterial;
  /** Darker brass for recessed interiors. */
  brassDark: THREE.MeshStandardMaterial;
  /**
   * The whiskey glass on the poker table: the saloon's original transparent
   * material (depthWrite:false so the amber liquid renders through).
   */
  whiskeyGlass: THREE.MeshStandardMaterial;
  /**
   * Bar glassware shell (tumblers, wine bowls, decanter): genuinely
   * transparent so liquids INSIDE render through it. depthWrite:false,
   * DoubleSide (the wine bowl is an open shell). This and whiskeyGlass are
   * the ONLY transparent materials in the saloon.
   */
  glass: THREE.MeshStandardMaterial;
}

const wood = (color: number): THREE.MeshStandardMaterial =>
  new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.04 });

const metal = (color: number, roughness = 0.35): THREE.MeshStandardMaterial =>
  new THREE.MeshStandardMaterial({ color, roughness, metalness: 0.85 });

/**
 * SHARED MATERIAL CACHE (weak-laptop perf revision).
 *
 * The old contract ("one material set per produced object") measured 1334
 * unique materials across 323 managed defs — pure GPU state churn and GC
 * pressure for zero visual benefit. Nothing mutates a saloon material after
 * creation (the flame/lampGlass looks are static emissives), so the set is
 * now a process-lifetime SINGLETON; meshes inside AND across objects share
 * one instance per look. Visual output is bit-identical.
 *
 * Disposal contract (revised with ThreeRendererAdapter): shared materials are
 * NEVER disposed per-object — the adapter now disposes geometries only.
 */
let saloonMaterialsCache: SaloonMaterials | null = null;

export function createSaloonMaterials(): SaloonMaterials {
  if (!saloonMaterialsCache) saloonMaterialsCache = buildSaloonMaterials();
  return saloonMaterialsCache;
}

function buildSaloonMaterials(): SaloonMaterials {
  return {
    woodDark: wood(SALOON_PALETTE.woodDark),
    woodMed: wood(SALOON_PALETTE.woodMed),
    woodLight: wood(SALOON_PALETTE.woodLight),
    brass: metal(SALOON_PALETTE.brass, 0.3),
    iron: metal(SALOON_PALETTE.iron, 0.4),
    glassDark: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.glassDark,
      roughness: 0.15,
      metalness: 0.55,
    }),
    felt: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.feltGreen,
      roughness: 0.95,
      metalness: 0,
    }),
    mirror: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.mirror,
      roughness: 0.08,
      metalness: 0.9,
    }),
    paper: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.paper,
      roughness: 1,
      metalness: 0,
    }),
    ink: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.ink,
      roughness: 0.9,
      metalness: 0,
    }),
    flame: new THREE.MeshStandardMaterial({
      color: SALOON_PALETTE.flame,
      emissive: SALOON_PALETTE.flame,
      emissiveIntensity: 1.6,
      roughness: 0.6,
    }),
    lampGlass: new THREE.MeshStandardMaterial({
      color: 0x3d2f1e,
      emissive: 0xff9a3d,
      emissiveIntensity: 0.55,
      roughness: 0.3,
      metalness: 0.2,
    }),
    ivory: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.ivory, roughness: 0.55, metalness: 0.02 }),
    leather: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.leather, roughness: 0.7, metalness: 0.05 }),
    leatherDark: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.leatherDark, roughness: 0.75, metalness: 0.05 }),
    silk: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.silk, roughness: 0.6, metalness: 0.05 }),
    amber: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.amber, roughness: 0.3, metalness: 0.05 }),
    wine: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.wine, roughness: 0.35, metalness: 0.05 }),
    // Opaque "glass" for bottles: glossy enough to read as glass, but never
    // transparent — a bottle must never vanish against the mirror behind it.
    bottleGreen: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.bottleGreen, roughness: 0.25, metalness: 0.15 }),
    bottleBrown: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.bottleBrown, roughness: 0.25, metalness: 0.15 }),
    bottleAmber: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.bottleAmber, roughness: 0.25, metalness: 0.15 }),
    bottleOlive: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.bottleOlive, roughness: 0.3, metalness: 0.12 }),
    cork: new THREE.MeshStandardMaterial({ color: SALOON_PALETTE.cork, roughness: 0.9, metalness: 0 }),
    brassDark: metal(0x6b5526, 0.5),
    whiskeyGlass: new THREE.MeshStandardMaterial({
      color: 0xaaccd8,
      roughness: 0.12,
      metalness: 0.1,
      transparent: true,
      opacity: 0.32,
      depthWrite: false,
    }),
    glass: new THREE.MeshStandardMaterial({
      color: 0xc9d6d2,
      roughness: 0.08,
      metalness: 0.05,
      transparent: true,
      opacity: 0.28,
      depthWrite: false,
      side: THREE.DoubleSide,
    }),
  };
}
